function percentOf(percent, total) {
  return (percent / 100) * total;
}

// 25% of 80
const part = percentOf(25, 80);
console.log('25% of 80 = ' + part);

// a 20% discount on a 50 dollar price
const price = 50;
const discount = percentOf(20, price);
const finalPrice = price - discount;
console.log('20% off 50 = ' + discount + ' off, pay ' + finalPrice);

