// applyDiscount(price, percentOff) -> price after the discount
function applyDiscount(price, percentOff) {
  // take percentOff% off the price
  const discount = percentOff * price; // <-- here
  return price - discount;
}

// applyDiscount(50, 20) should be 40
console.log(applyDiscount(50, 20)); // prints -950
